WITH first_order AS (SELECT customer_id,MIN(order_date) first_date FROM orders GROUP BY customer_id),eligible AS (SELECT * FROM first_order WHERE date(first_date,'+90 days')<='2025-12-31'), flags AS (SELECT e.customer_id,substr(e.first_date,1,7) cohort_month,MAX(CASE WHEN o.order_date>e.first_date AND o.order_date<=date(e.first_date,'+90 days') THEN 1 ELSE 0 END) repeat_90 FROM eligible e JOIN orders o USING(customer_id) GROUP BY e.customer_id,e.first_date) SELECT cohort_month,COUNT(*) eligible_customers,SUM(repeat_90) repeat_customers,AVG(repeat_90) repeat_rate FROM flags GROUP BY cohort_month ORDER BY cohort_month
